if mode not in ("dry", "apply"):
    raise SystemExit("режим: dry | apply")
dry = mode == "dry"
factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
now = moscow_now()
ACTOR = Actor(id=UUID(int=0), name="Термоусадка отрезками: цена за метр 25.10.2026", department="System")

done = same = refused = missing = 0
with factory() as uow:
    by_name = {str(r.fields.get("Наименование", "")).strip(): r.id
               for r in uow.tech_operations.list(tab=TechOperationTab.MATERIAL, query="", limit=100_000)}
for item in PAYLOAD["fill"]:
    name = item["fields"]["Наименование"]
    record_id = by_name.get(name)
    if record_id is None:
        missing += 1
        continue
    with factory() as uow:
        record = uow.tech_operations.get(record_id)
        edits = tuple(FieldEdit(key, item["old"][key], value) for key, value in item["fields"].items()
                      if key != "Наименование" and str(record.fields.get(key, "")).strip() != value)
        if not edits:
            same += 1
            continue
        try:
            before, _ = _edit_in(record_id, edits, now, uow)
        except (StaleRecordError, ReferenceValidationError, LookupError) as error:
            refused += 1
            print(f"   отказ: {name} ({error})")
            continue
        _audit("references.tech_record_edited", ACTOR, now, {"record_id": str(before.id), "tab": before.tab.value,
               "fields": [edit.field for edit in edits], "reason": "термоусадка отрезками: цена за метр (владелец 25.10.2026)"}, uow)
        if not dry:
            uow.commit()
        done += 1
print(f"== цена за метр: {'проверено' if dry else 'записано'} {done}, уже так {same}, отказ {refused}, нет строки {missing}")
print("ИТОГО", "(проверка, ничего не записано)" if dry else "(записано)")
